using System.Linq;
namespace ZapretDesk {public static class TestDiagnostics48 {
 static void Check(bool x,string m){if(!x)throw new System.Exception(m);}
 public static async System.Threading.Tasks.Task<string> Run(){string dir=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"veyra-diagnostic-"+System.Guid.NewGuid().ToString("N"));System.IO.Directory.CreateDirectory(dir);try{var unsafeMessage="DO-NOT-RECORD-password-or-proxy-key";var nested=new System.IO.IOException(unsafeMessage,new System.Net.WebException(unsafeMessage,new System.Net.Sockets.SocketException((int)System.Net.Sockets.SocketError.HostNotFound)));string description=TelegramDiagnostics.Describe(nested);Check(!description.Contains(unsafeMessage)&&description.Contains("HostNotFound"),"Redacted exception types/codes");Check(TelegramDiagnostics.Describe(new TelegramCloseException(1008)).Contains("Close=1008"),"WebSocket close code");for(int i=0;i<260;i++)TelegramDiagnostics.Write(dir,"TEST "+i);var lines=System.IO.File.ReadAllLines(System.IO.Path.Combine(dir,"telegram-diagnostic.txt"));Check(lines.Length==192&&lines.Last().EndsWith("TEST 259"),"Bounded latest events");
 var secret=TgProtocol.Random(16);using(var bridge=new TelegramBridge(secret,(d,m,t)=>{throw nested;},line=>TelegramDiagnostics.Write(dir,line))){bridge.Start(0);using(var client=new System.Net.Sockets.TcpClient()){await client.ConnectAsync(System.Net.IPAddress.Loopback,bridge.Port);var raw=TgProtocol.Random(64);System.Buffer.BlockCopy(System.BitConverter.GetBytes(0xddddddddU),0,raw,56,4);System.Buffer.BlockCopy(System.BitConverter.GetBytes((short)4),0,raw,60,2);using(var tx=new TgCtr(TgProtocol.Hash(TgProtocol.Slice(raw,8,32),secret),TgProtocol.Slice(raw,40,16))){var hello=(byte[])raw.Clone();var enc=tx.Apply(raw);System.Buffer.BlockCopy(enc,56,hello,56,8);await client.GetStream().WriteAsync(hello,0,64);for(int i=0;i<200&&bridge.Error=="";i++)await System.Threading.Tasks.Task.Delay(10);Check(bridge.Error.Contains("DC4")&&bridge.Error.Contains("WebSocket/TLS")&&bridge.Error.Contains("telegram-diagnostic.txt"),"Failure phase and DC in UI");}}}
 string log=System.IO.File.ReadAllText(System.IO.Path.Combine(dir,"telegram-diagnostic.txt"));Check(log.Contains("HostNotFound")&&log.Contains("FAIL DC=4 phase=WebSocket/TLS"),"Underlying error recorded");Check(!log.Contains(unsafeMessage)&&!log.Contains(System.BitConverter.ToString(secret).Replace("-","").ToLowerInvariant()),"No exception messages/proxy secrets recorded");return "PASS: synthetic DNS failure captured with DC/phase/inner codes; no raw exception messages or secrets; close-code reporting; bounded 192-event report.";}finally{System.IO.Directory.Delete(dir,true);}}
}}
